pub fn bash_env_binding_spelling(b: Rc<EnvBinding>) -> String {
    match (*b.clone()).clone() {
    EnvBinding::EnvSet { name: n, value: v, .. } => v1_rt::concat(v1_rt::concat(n.clone(), "=".to_string()), v1_rt::concat(v.clone(), " ".to_string())),
    EnvBinding::EnvUnset { name: n, .. } => v1_rt::concat("env -u ".to_string(), v1_rt::concat(n.clone(), " ".to_string())),
}
}

pub fn bash_env_prefix(env: Rc<FreeMonoid<Rc<EnvBinding>>>) -> String {
    crate::std_algebra::fold_list_right(env, "".to_string(), |acc, b| v1_rt::concat(bash_env_binding_spelling(b), acc.clone()))
}

